<link rel="stylesheet" href="{{ asset('vendors/summernote/summernote-lite.min.css') }}">
<style>
.news-module .news-section-card{border:1px solid var(--phoenix-border-color);border-radius:.5rem;padding:1rem;margin-bottom:1rem}.news-module .news-preview{width:5rem;height:4rem;object-fit:cover;border-radius:.35rem}.news-module .note-editor{border-color:var(--phoenix-border-color);background:var(--phoenix-emphasis-bg)}.news-module .note-toolbar,.news-module .note-editing-area,.news-module .note-statusbar{background:var(--phoenix-card-bg);color:var(--phoenix-body-color);border-color:var(--phoenix-border-color)}.news-module .note-editable{color:var(--phoenix-body-color)}.news-module .news-save-button{position:fixed;top:calc(var(--phoenix-navbar-top-height, 4rem) + 1.5rem);right:1.5rem;z-index:1030}@media (max-width:767.98px){.news-module .news-save-button{top:auto;bottom:1rem;right:1rem;box-shadow:0 .5rem 1.25rem rgba(0,0,0,.25)}.news-module .news-section-card{padding:.75rem}.news-module{padding-bottom:4rem}}.news-toast{position:fixed;top:5rem;left:50%;transform:translateX(-50%);z-index:2100;width:min(34rem,92vw)}
</style>
