   <div class="col-md-4"><label class="form-label">Category <span class="text-danger">*</span></label><select class="form-select" name="cat_id" data-cat-level="1" required><option value="">Choose category</option></select><div class="invalid-feedback"></div></div>
   <div class="col-md-4"><label class="form-label">Sub category</label><select class="form-select" name="cat_child_1" data-cat-level="2" disabled><option value="">Choose sub category</option></select><div class="invalid-feedback"></div></div>
   <div class="col-md-4"><label class="form-label">Sub-sub category</label><select class="form-select" name="cat_child_2" data-cat-level="3" disabled><option value="">Choose sub-sub category</option></select><div class="invalid-feedback"></div></div>
  </div></div></div>
  <div class="card mb-3"><div class="card-header"><h4 class="card-title mb-0">News info</h4></div><div class="card-body"><div class="row g-3">
   <div class="col-md-4"><label class="form-label">News status</label><select class="form-select" name="news_status">@foreach(config('news.status') as $key=>$label)<option value="{{ $key }}" @selected($key === config('news.default_status'))>{{ $label }}</option>@endforeach</select><div class="invalid-feedback"></div></div>
   <div class="col-md-4"><label class="form-label">News type</label><select class="form-select" name="news_type">@foreach(($newsTypes ?? []) as $type)<option value="{{ $type->news_type_id }}">{{ $type->type_name }}</option>@endforeach</select><div class="invalid-feedback"></div></div>
