  <div class="card mb-3"><div class="card-header"><h4 class="card-title mb-0">Tags</h4></div><div class="card-body"><label class="form-label">Tags</label><input class="form-control" data-tags placeholder="Type a tag and press Enter or comma"><div class="form-text">Up to 20 tags, 250 characters each.</div><div class="invalid-feedback"></div></div></div>
  <div class="card mb-3"><div class="card-header"><h4 class="card-title mb-0">Reporter</h4></div><div class="card-body">
