   <p class="text-body-tertiary fs-9 mb-0 d-none" data-reporters-empty>No reporters saved yet. Type the first reporter's name below.</p>
   <button class="btn btn-phoenix-primary btn-sm" type="button" data-add-reporter>+ Add another reporter</button>
   <hr class="my-3">
   <label class="form-label">New reporter</label><input class="form-control" name="reporter_name" maxlength="250" placeholder="Type a name"><div class="invalid-feedback"></div><div class="form-text">Not in the list? Type the name here. Separate several names with commas.</div>
  </div></div>
  <div class="card mb-3"><div class="card-header"><h4 class="card-title mb-0">News source</h4></div><div class="card-body row g-3"><div class="col-md-6"><label class="form-label">Source</label><input class="form-control" name="news_source" maxlength="150"><div class="invalid-feedback"></div></div><div class="col-md-6"><label class="form-label">Source link</label><input class="form-control" name="news_source_link" type="url" maxlength="500"><div class="invalid-feedback"></div></div></div></div>
  <div class="card mb-4"><div class="card-header"><h4 class="card-title mb-0">SEO</h4></div><div class="card-body row g-3"><div class="col-12"><label class="form-label">SEO title</label><input class="form-control" name="seo_title" maxlength="250"><div class="invalid-feedback"></div></div><div class="col-12"><label class="form-label">SEO keywords</label><input class="form-control" name="seo_keyword" maxlength="350"><div class="invalid-feedback"></div></div><div class="col-12"><label class="form-label">SEO description</label><textarea class="form-control" name="seo_description" maxlength="400" rows="3"></textarea><div class="invalid-feedback"></div></div></div></div>
 </form>
</div></template>
<div class="news-toast d-none" data-news-toast></div>
<script src="{{ asset('vendors/choices/choices.min.js') }}"></script><script src="{{ asset('vendors/jquery/jquery.min.js') }}"></script><script src="{{ asset('vendors/summernote/summernote-lite.min.js') }}"></script>
<script>
(function(){
 const cfg=document.getElementById('news-config'), root=document.getElementById('news-module-template').content.firstElementChild;
 const mount=()=>{const host=document.getElementById('portal-module-host');if(!host)return false;host.replaceChildren(root);init();return true};
 if(!mount()){const ob=new MutationObserver(()=>{if(mount())ob.disconnect()});ob.observe(document.body,{childList:true,subtree:true})}
 function init(){const form=root.querySelector('#news-form'), csrf=document.querySelector('meta[name=csrf-token]').content, sections=root.querySelector('[data-sections]'), newsType=root.querySelector('[name="news_type"]');let categoryRows=[],reporterRows=[];
  fetch(cfg.dataset.categories,{headers:{Accept:'application/json'}}).then(r=>r.json()).then(j=>{categoryRows=(j.data||[]).filter(x=>Number(x.status)===1);fillCat(1,null)});
  function fillCat(level,parent){const sel=root.querySelector('[data-cat-level="'+level+'"]'), label=sel.options[0].text;sel.innerHTML='';sel.add(new Option(label,''));const rows=categoryRows.filter(x=>Number(x.level)===level&&(level===1?x.parent_id===null:Number(x.parent_id)===Number(parent)));rows.forEach(x=>sel.add(new Option(x.name,x.id)));sel.disabled=!rows.length;if(level<3)fillCat(level+1,null)}
  root.querySelectorAll('[data-cat-level]').forEach(sel=>sel.addEventListener('change',()=>{const level=Number(sel.dataset.catLevel);if(level<3)fillCat(level+1,sel.value||null)}));
  function loadReporters(){return fetch(cfg.dataset.reporters,{headers:{Accept:'application/json'}}).then(r=>r.json()).then(j=>{reporterRows=j.data||[]})}loadReporters().then(renderReporters);
  function renderReporters(){const box=root.querySelector('[data-reporters]'),has=reporterRows.length>0;box.innerHTML='';root.querySelector('[data-add-reporter]').classList.toggle('d-none',!has);root.querySelector('[data-reporters-label]').classList.toggle('d-none',!has);root.querySelector('[data-reporters-empty]').classList.toggle('d-none',has);if(has)addReporter()}
  function syncReporters(){const selects=[...root.querySelectorAll('[data-reporters] select')],chosen=selects.map(s=>s.value).filter(Boolean);selects.forEach(s=>[...s.options].forEach(o=>{o.disabled=o.value!==''&&o.value!==s.value&&chosen.includes(o.value)}));root.querySelector('[data-add-reporter]').disabled=selects.length>=reporterRows.length}
  function addReporter(){const box=root.querySelector('[data-reporters]');if(box.querySelectorAll('select').length>=reporterRows.length)return;const wrap=document.createElement('div');wrap.className='input-group mb-2';const select=document.createElement('select');select.className='form-select';select.name='reporter_names[]';select.innerHTML='<option value="">Select reporter</option>';reporterRows.forEach(n=>select.add(new Option(n,n)));select.onchange=syncReporters;wrap.append(select);if(box.querySelectorAll('select').length){const rm=document.createElement('button');rm.type='button';rm.className='btn btn-phoenix-danger';rm.title='Remove reporter';rm.setAttribute('aria-label','Remove reporter');rm.textContent='\u00d7';rm.onclick=()=>{wrap.remove();syncReporters()};wrap.append(rm)}box.append(wrap);syncReporters()}
  function renumber(){const cards=[...sections.children];cards.forEach((c,i)=>{c.querySelector('[data-number]').textContent=i+1;c.querySelector('[data-remove]').classList.toggle('d-none',i===0);c.querySelector('[data-remove]').onclick=()=>{if($(c.querySelector('[data-text]')).next('.note-editor').length)$(c.querySelector('[data-text]')).summernote('destroy');c.remove();renumber()};c.querySelectorAll('[data-image],[data-video],[data-caption],[data-text],[data-kind],[data-cover]').forEach(el=>el.name='sections['+i+']['+({image:'image',video:'video_link',caption:'caption',text:'text',kind:'media_type',cover:'is_cover'}[el.dataset.image!==undefined?'image':el.dataset.video!==undefined?'video':el.dataset.caption!==undefined?'caption':el.dataset.text!==undefined?'text':el.dataset.kind!==undefined?'kind':'cover'])+']');});const imgs=cards.filter(c=>!c.querySelector('[data-kind]').checked);let cover=imgs.find(c=>c.querySelector('[data-cover]').checked)||imgs[0];cards.forEach(c=>{const radio=c.querySelector('[data-cover]');radio.checked=c===cover;radio.disabled=c.querySelector('[data-kind]').checked;});root.querySelector('[data-add-section]').disabled=cards.length>=30}
  function applyNewsTypeToSection(card){const selectedType=(newsType.selectedOptions[0]?.textContent||'').trim().toLowerCase();const useVideo=selectedType.includes('video');const kind=card.querySelector('[data-kind]');kind.checked=useVideo;card.querySelector('[data-image-wrap]').classList.toggle('d-none',useVideo);card.querySelector('[data-video-wrap]').classList.toggle('d-none',!useVideo);card.querySelector('[data-kind-label]').textContent=useVideo?'Video para (switch to image)':'Image para (switch to video)'}
  newsType.addEventListener('change',()=>{[...sections.children].forEach(applyNewsTypeToSection);renumber()});
  function addSection(){if(sections.children.length>=30)return;const c=document.getElementById('news-section-template').content.firstElementChild.cloneNode(true);sections.append(c);const kind=c.querySelector('[data-kind]');kind.onchange=()=>{c.querySelector('[data-image-wrap]').classList.toggle('d-none',kind.checked);c.querySelector('[data-video-wrap]').classList.toggle('d-none',!kind.checked);c.querySelector('[data-kind-label]').textContent=kind.checked?'Video para (switch to image)':'Image para (switch to video)';renumber()};c.querySelector('[data-cover]').onchange=()=>{sections.querySelectorAll('[data-cover]').forEach(r=>{if(r!==c.querySelector('[data-cover]'))r.checked=false})};c.querySelector('[data-image]').onchange=e=>{const f=e.target.files[0],p=c.querySelector('[data-preview]');if(f){p.src=URL.createObjectURL(f);p.classList.remove('d-none')}};$(c.querySelector('[data-text]')).summernote({height:180,toolbar:[['style',['style']],['font',['bold','italic','underline']],['para',['ul','ol']],['insert',['link']],['history',['undo','redo']]],styleTags:['p','h2','h3','h4']});applyNewsTypeToSection(c);renumber();root.querySelector('[data-add-section]').disabled=sections.children.length>=30}
  root.querySelector('[data-add-section]').onclick=addSection;root.querySelector('[data-add-reporter]').onclick=addReporter;addSection();
  const tagsInput=root.querySelector('[data-tags]');let choices=null;if(window.Choices)choices=new Choices(tagsInput,{delimiter:',',editItems:true,duplicateItemsAllowed:false,removeItemButton:true,addItems:true,addItemFilter:v=>v.trim().length>0&&v.length<=250,customAddItemText:v=>v.length>250?'Tag must be 250 characters or fewer': 'Press Enter to add <b>'+v+'</b>',maxItemCount:20,shouldSort:false});
  function errors(map){const unmatched=[];root.querySelectorAll('.is-invalid').forEach(x=>x.classList.remove('is-invalid'));root.querySelectorAll('.invalid-feedback').forEach(x=>{x.textContent='';x.classList.remove('d-block')});Object.entries(map||{}).forEach(([key,msgs])=>{if(key==='sections'){const fb=root.querySelector('[data-error="sections"]');fb.textContent=msgs[0];fb.classList.add('d-block');return}const m=key.match(/^sections\.(\d+)\.(image|video_link|text|caption)$/);let el;if(m){const c=sections.children[m[1]];el=c&&c.querySelector('[data-'+({image:'image',video_link:'video',caption:'caption',text:'text'}[m[2]])+']')}else el=form.querySelector('[name="'+key+'"]');if(el){el.classList.add('is-invalid');const fb=el.parentElement.querySelector('.invalid-feedback');if(fb)fb.textContent=msgs[0]}else unmatched.push(key+': '+(msgs||[]).join(' '))});return unmatched}
  function showError(message,details){document.querySelectorAll('[data-news-error]').forEach(n=>n.remove());const alert=document.createElement('div');alert.className='news-toast alert alert-subtle-danger';alert.setAttribute('role','alert');alert.dataset.newsError='1';const title=document.createElement('div');title.className='fw-bold pe-4';title.textContent=message||'Unable to save news.';alert.append(title);if(details&&details.length){const list=document.createElement('ul');list.className='mb-0 mt-2';details.forEach(text=>{const item=document.createElement('li');item.textContent=text;list.append(item)});alert.append(list)}const close=document.createElement('button');close.type='button';close.className='btn-close position-absolute top-0 end-0 m-2';close.setAttribute('aria-label','Close');close.onclick=()=>alert.remove();alert.append(close);document.body.append(alert)}
  form.onsubmit=async e=>{e.preventDefault();errors({});const fd=new FormData(form);Array.from(fd.keys()).filter(k=>k.startsWith('sections[')||k==='tags[]'||k==='tags'||k==='reporter_names[]').forEach(k=>fd.delete(k));[...sections.children].forEach((c,i)=>{fd.append(`sections[${i}][media_type]`,c.querySelector('[data-kind]').checked?'2':'1');fd.append(`sections[${i}][caption]`,c.querySelector('[data-caption]').value);fd.append(`sections[${i}][text]`,$(c.querySelector('[data-text]')).summernote('code'));fd.append(`sections[${i}][is_cover]`,c.querySelector('[data-cover]').checked?'1':'0');if(c.querySelector('[data-kind]').checked)fd.append(`sections[${i}][video_link]`,c.querySelector('[data-video]').value);else if(c.querySelector('[data-image]').files[0])fd.append(`sections[${i}][image]`,c.querySelector('[data-image]').files[0])});root.querySelectorAll('[data-reporters] select').forEach(select=>{if(select.value)fd.append('reporter_names[]',select.value)});if(choices)choices.getValue(true).forEach(v=>fd.append('tags[]',v));try{const r=await fetch(cfg.dataset.store,{method:'POST',headers:{Accept:'application/json','X-CSRF-TOKEN':csrf,'X-Requested-With':'XMLHttpRequest'},body:fd});let j;try{j=await r.json()}catch(parseError){showError('The server returned an unreadable response (HTTP '+r.status+').');return}if(!r.ok){const unmatched=errors(j.errors||{});showError(j.message||('Request failed (HTTP '+r.status+').'),unmatched);return}const toast=document.createElement('div');toast.className='news-toast alert alert-subtle-success';toast.textContent='News saved. ID: '+j.id;document.body.append(toast);setTimeout(()=>toast.remove(),5000);form.reset();[...sections.children].forEach(c=>$(c.querySelector('[data-text]')).summernote('destroy'));sections.innerHTML='';addSection();if(choices)choices.removeActiveItems();loadReporters().then(renderReporters);fillCat(1,null)}catch(err){showError('Network error. The news could not be saved.',[err.message||'The request did not reach the server.'])}};
 }
})();
</script>
